-- Rescheduling: DEMO-0031 approved (moved +3 days), DEMO-0032 pending, DEMO-0033 rejected
UPDATE `reservations` SET `booking_date` = `booking_date` + INTERVAL 3 DAY, `start_at` = `start_at` + INTERVAL 3 DAY, `end_at` = `end_at` + INTERVAL 3 DAY, `reschedule_count` = 1
WHERE `reservation_code` = 'DEMO-0031' AND `reschedule_count` = 0
  AND NOT EXISTS (SELECT 1 FROM `rescheduling_requests` r JOIN `reservations` x ON x.reservation_id = r.reservation_id WHERE x.reservation_code = 'DEMO-0031');
SELECT r.reservation_id, r.booking_date - INTERVAL 3 DAY, r.booking_date, r.booking_type, '[DEMO] Family schedule changed', CURDATE() - INTERVAL 4 DAY, 'CUSTOMER', 'APPROVED', NOW() - INTERVAL 3 DAY, '[DEMO] New date available', 1
FROM `reservations` r WHERE r.reservation_code = 'DEMO-0031' AND NOT EXISTS (SELECT 1 FROM `rescheduling_requests` q WHERE q.reservation_id = r.reservation_id);
SELECT r.reservation_id, 'CONFIRMED', 'CONFIRMED', CONCAT('[DEMO] Rescheduled from ', r.booking_date - INTERVAL 3 DAY, ' to ', r.booking_date)
FROM `reservations` r WHERE r.reservation_code = 'DEMO-0031' AND NOT EXISTS (SELECT 1 FROM `reservation_status_history` h WHERE h.reservation_id = r.reservation_id AND h.remarks LIKE '[DEMO] Rescheduled%');
SELECT r.reservation_id, r.booking_date, r.booking_date + INTERVAL 7 DAY, r.booking_type, '[DEMO] Conflict with a family event', CURDATE() - INTERVAL 1 DAY, 'CUSTOMER', 'PENDING', 1
FROM `reservations` r WHERE r.reservation_code = 'DEMO-0032' AND NOT EXISTS (SELECT 1 FROM `rescheduling_requests` q WHERE q.reservation_id = r.reservation_id);
SELECT r.reservation_id, r.booking_date, r.booking_date + INTERVAL 2 DAY, r.booking_type, '[DEMO] Weather concerns', CURDATE() - INTERVAL 10 DAY, 'CUSTOMER', 'REJECTED', NOW() - INTERVAL 9 DAY, '[DEMO] Requested date already booked', 1
FROM `reservations` r WHERE r.reservation_code = 'DEMO-0033' AND NOT EXISTS (SELECT 1 FROM `rescheduling_requests` q WHERE q.reservation_id = r.reservation_id);
SELECT 'Quirino Salazar', 'quirino.salazar.demo042@example.com', '09990000042', '[DEMO] Birthday party for 30 guests', 'Hello, is Area 1 available for a 7th birthday next month? We are around 30 people.', 'NEW', 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `inquiries` WHERE `subject` = '[DEMO] Birthday party for 30 guests');
SELECT 'Noel Yap', 'noel.yap.demo043@example.com', '09990000043', '[DEMO] Overnight stay question', 'Can we bring our own sound system for the overnight package?', 'READ', 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `inquiries` WHERE `subject` = '[DEMO] Overnight stay question');
SELECT 'Cecilia Buenaventura', 'cecilia.buenaventura.demo044@example.com', '09990000044', '[DEMO] Payment method', 'Do you accept bank transfer for the down payment?', 'REPLIED', 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `inquiries` WHERE `subject` = '[DEMO] Payment method');
SELECT 'payment', r.reservation_id, 'Payment awaiting verification', CONCAT(r.reservation_code, ' - ', r.guest_name, ' submitted a down payment (DEMO)'), CONCAT('admin/reservation.php?id=', r.reservation_id), 0
FROM `reservations` r WHERE r.reservation_code IN ('DEMO-0025','DEMO-0026','DEMO-0027')
  AND NOT EXISTS (SELECT 1 FROM `notifications` n WHERE n.reservation_id = r.reservation_id AND n.type = 'payment');
SELECT 'reschedule', r.reservation_id, 'Reschedule request', CONCAT(r.reservation_code, ' asked to move their booking (DEMO)'), 'admin/reschedules.php', 0
FROM `reservations` r WHERE r.reservation_code = 'DEMO-0032'
  AND NOT EXISTS (SELECT 1 FROM `notifications` n WHERE n.reservation_id = r.reservation_id AND n.type = 'reschedule');
COMMIT;

